-- Rating per percent (wowsims base stats; the generated data has the same numbers)
local function ratingPer(kind)
  local r = data().ratings or {}
  local d = { hit = 10, crit = 14, haste = 10, exp = 10, dodge = 12, parry = 15, block = 5, def = 1 }
  return r[kind] or d[kind]
end

-- Equip lines the game writes as text (English), for stats it doesn't report as numbers: "Improves your chance to
-- get a critical strike by 1%." counts as 14 crit rating (rating per percent from wowsims).
local SCHOOLS = { arcane = "sp_arcane", fire = "sp_fire", frost = "sp_frost", holy = "sp_holy", nature = "sp_nature",
  shadow = "sp_shadow" }
local LINES = {
  { "increases damage and healing done by magical spells and effects by up to (%d+)", { "sp", "heal" } },
  { "increases healing done by spells and effects by up to (%d+)", "heal" },
  { "increases damage done by (%a+) spells and effects by up to (%d+)", "school" },
  { "improves your chance to hit with spells by (%d+)%%", "hit", "hit" },
  { "improves your chance to hit by (%d+)%%", "hit", "hit" },
  { "improves your chance to get a critical strike with spells by (%d+)%%", "crit", "crit" },
  { "improves your chance to get a critical strike by (%d+)%%", "crit", "crit" },
  { "increases your chance to dodge an attack by (%d+)%%", "dodge", "dodge" },
  { "increases your chance to parry an attack by (%d+)%%", "parry", "parry" },
  { "increases your chance to block attacks with a shield by (%d+)%%", "block", "block" },
  { "increases the block value of your shield by (%d+)", "bv" },
  { "increased defense %+(%d+)", "def" },
  { "%+(%d+) ranged attack power", "rap" },
  { "%+(%d+) attack power", "ap" },
  { "increases attack power by (%d+) in cat, bear, dire bear, and moonkin forms only", "fap" },
  { "restores (%d+) mana per 5 sec", "mp5" },
  { "restores (%d+) health per 5 sec", "hp5" },
}

-- Adds what one tooltip or effect line says to st (the larger value wins where the game already reported it).
function U.parseLine(st, line)
  if type(line) ~= "string" then return false end
  local l = line:lower():gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
  for _, p in ipairs(LINES) do
    local a, b = l:match(p[1])
    if a then
      local function put(k, v) v = tonumber(v); if v and v > (st[k] or 0) then st[k] = v end end
      if p[2] == "school" then
        local k = SCHOOLS[a]
        if k then put(k, b) end
      elseif type(p[2]) == "table" then
        for _, k in ipairs(p[2]) do put(k, a) end
      else
        put(p[2], p[3] and (tonumber(a) * ratingPer(p[3])) or a)
      end
      return true
    end
  end
  return false
end

