-- Saved settings: account-wide (db.up) and per character (EverlookAuctionsCharDB.up)

U.DEFAULTS = { scenario = "solo", tip = true, bags = true, chat = true, quest = true, junk = false, procs = true, armor = true,
  talents = true, pawn = false, rich = false, min = 0, max = nil }

function U.db()
  local d = ns.db and ns.db()
  if type(d) ~= "table" then return nil end
  d.up = d.up or {}
  d.up.profiles = d.up.profiles or {}
  return d.up
end

function U.char()
  EverlookAuctionsCharDB = EverlookAuctionsCharDB or {}
  local c = EverlookAuctionsCharDB
  c.up = c.up or {}
  c.up.specs = c.up.specs or {}
  c.up.profile = c.up.profile or {}
  return c.up
end

function U.get(key)
  local d = U.db()
  local v = d and d[key]
  if v == nil then return U.DEFAULTS[key] end
  return v
end

function U.set(key, v)
  local d = U.db()
  if d then d[key] = v end
  U.changed()
end

function U.class()
  if U.testClass then return U.testClass end
  local okC, _, class = pcall(UnitClass, "player")
  return okC and class or "WARRIOR"
end

function U.level()
  if U.testLevel then return U.testLevel end
  local okL, l = pcall(UnitLevel, "player")
  return okL and tonumber(l) or 60
end

-- The specs this character gears for: the ones ticked, or every spec of the class until one is picked (then the
-- second return is true: all of them are counted).
function U.ticked()
  local c = U.char()
  local out = {}
  for _, s in ipairs(U.specs()) do if c.specs[s.key] then out[#out + 1] = s end end
  if #out == 0 then
    -- none picked: the talent-tree specs (levelling builds only when picked)
    for _, s in ipairs(U.specs()) do if not s.build then out[#out + 1] = s end end
    return out, true
  end
  return out, false
end

function U.setSpecs(keys)
  local c = U.char()
  c.specs = {}
  for _, k in ipairs(keys) do c.specs[k] = true end
  c.asked = true
  U.changed()
end

-- Profiles of the player's own: per class, a list of { name, spec, w }.
function U.profiles(spec)
  local d = U.db()
  if not d then return {} end
  d.profiles[U.class()] = d.profiles[U.class()] or {}
  local all = d.profiles[U.class()]
  if not spec then return all end
  local out = {}
  for _, p in ipairs(all) do if p.spec == spec then out[#out + 1] = p end end
  return out
end

function U.activeProfile(spec)
  local name = U.char().profile[spec]
  if not name then return nil end
  for _, p in ipairs(U.profiles(spec)) do if p.name == name then return p end end
  U.char().profile[spec] = nil
end

-- Pawn's scale for the spec, when Pawn is installed and the setting is on: a visible scale of this class whose name
-- has the spec's name in it. Read only.
function U.pawnScale(spec)
  if not U.get("pawn") then return nil end
  local pc = rawget(_G, "PawnCommon")
  if type(pc) ~= "table" or type(pc.Scales) ~= "table" then return nil end
  local okC, _, _, classID = pcall(UnitClass, "player")
  local want = spec.name:lower()
  for name, sc in pairs(pc.Scales) do
    if type(sc) == "table" and type(sc.Values) == "table" and (not sc.ClassID or sc.ClassID == (okC and classID))
        and tostring(sc.LocalizedName or name):lower():find(want, 1, true) then
      local w = U.fromPawnValues(sc.Values)
      if next(w) then return w, tostring(sc.LocalizedName or name) end
    end
  end
end

-- The weights in use for a spec: your own profile when one is picked, else Pawn's scale (when that setting is on),
-- else the built-in ones (adjusted to your talents when that setting is on). Returns the weights, the stats a
-- talent changed, and where they're from ("profile", "pawn" or "built-in").
local weightCache = {}
function U.weights(spec)
  if type(spec) == "string" then spec = U.spec(spec) end
  if not spec then return {}, {}, "none" end
  local hit = weightCache[spec.key]
  if hit then return hit[1], hit[2], hit[3], hit[4], hit[5] end
  local w, why, from, label
  local meta = {}
  local p = U.activeProfile(spec.key)
  if p then
    w, why, from, label = p.w, {}, "profile", p.name
  else
    local pw, pname = U.pawnScale(spec)
    if pw then
      w, why, from, label = pw, {}, "pawn", pname
    else
      local ranks
      if U.get("talents") then
        local t = U.testTalents or U.readTalents()
        ranks = function(tab, tier, col, name)
          local byName = name and t["name:" .. name]
          if byName then return byName end
          return t[tab .. ":" .. tier .. ":" .. col]
        end
      end
      local alt
      w, why, alt = U.adjusted(spec, U.classData(), ranks, U.level())
      local _, br = U.bracket(spec)
      from, label = "built-in", br and ("Built-in, level " .. U.bracketText(spec, br)) or "Built-in"
      if br then
        meta = U.bracketMeta(br)
        if alt then meta.se, meta.mana = alt.se, alt.mana end
        if br.scenario and U.SCENARIOS[br.scenario] then label = label .. ", " .. U.SCENARIOS[br.scenario]:lower() end
        if meta.src == "estimate" then label = label .. " (estimate)" end
        -- a mana-dependent stat never counts against an item
        for k in pairs(meta.mana or {}) do if (w[k] or 0) < 0 then w[k] = nil end end
      end
    end
  end
  weightCache[spec.key] = { w, why, from, label, meta }
  return w, why, from, label, meta
end

---------------------------------------------------------------------------------------------------------------------
-- Import and export

local PAWN = {
  strength = "str", agility = "agi", stamina = "sta", intellect = "int", spirit = "spi",
  attackpower = "ap", ap = "ap", rangedattackpower = "rap", rap = "rap", feralattackpower = "fap", feralap = "fap",
  spelldamage = "sp", spellpower = "sp", healing = "heal", healingpower = "heal",
  arcanespelldamage = "sp_arcane", firespelldamage = "sp_fire", frostspelldamage = "sp_frost",
  holyspelldamage = "sp_holy", naturespelldamage = "sp_nature", shadowspelldamage = "sp_shadow",
  hitrating = "hit", hit = "hit", spellhitrating = "hit", spellhit = "hit",
  critrating = "crit", crit = "crit", spellcritrating = "crit", spellcrit = "crit",
  hasterating = "haste", haste = "haste", spellhasterating = "haste",
  expertiserating = "exp", expertise = "exp", armorpenetration = "arp", armorpenetrationrating = "arp",
  spellpenetration = "spen", defenserating = "def", defense = "def", dodgerating = "dodge", dodge = "dodge",
  parryrating = "parry", parry = "parry", blockrating = "block", block = "block", blockvalue = "bv",
  armor = "armor", health = "health", mana = "mana", mp5 = "mp5", hp5 = "hp5",
  dps = "mhdps", meleedps = "mhdps", mainhanddps = "mhdps", offhanddps = "ohdps", rangeddps = "rdps",
}

function U.fromPawnValues(values)
  local w = {}
  for k, v in pairs(values or {}) do
    local key = PAWN[tostring(k):lower()]
    v = tonumber(v)
    if key and v and v ~= 0 then
      w[key] = v
      if key == "mhdps" and tostring(k):lower() == "dps" then
        w.ohdps, w.rdps = w.ohdps or v, w.rdps or v   -- Pawn's plain DPS counts for every weapon
      end
    end
  end
  return w
end

-- Our string: "EAH-UP:1:<CLASS>:<spec>:<name>:str=2.2,agi=1.7,..." (values rounded to 3 decimals).
function U.export(w, spec, name)
  local parts = {}
  for _, s in ipairs(U.STATS) do
    local v = w[s[1]]
    if v and v ~= 0 then parts[#parts + 1] = s[1] .. "=" .. (("%.3f"):format(v):gsub("0+$", ""):gsub("%.$", "")) end
  end
  return ("EAH-UP:1:%s:%s:%s:%s"):format(U.class(), spec or "", (tostring(name or ""):gsub("[:|]", "")), table.concat(parts, ","))
end

-- Reads our string or Pawn's "( Pawn: v1: "Name": Strength=2.2, Agility=1.7 )". Returns { name, spec, class, w },
-- or nil and why.
function U.import(text)
  text = tostring(text or ""):gsub("||", "|")
  local class, spec, name, body = text:match("EAH%-UP:1:(%u*):([%w_]*):([^:]*):([%w_=%.,%-]*)")
  if body then
    local w = {}
    for k, v in body:gmatch("([%w_]+)=(%-?[%d%.]+)") do
      if U.NAME[k] and tonumber(v) and tonumber(v) ~= 0 then w[k] = tonumber(v) end
    end
    if not next(w) then return nil, "no weights in it" end
    return { name = name ~= "" and name or "Imported", spec = spec ~= "" and spec or nil, class = class ~= "" and class or nil, w = w }
  end
  local pname, pbody = text:match("%(%s*Pawn%s*:%s*v1%s*:%s*\"([^\"]*)\"%s*:%s*(.-)%s*%)")
  if pbody then
    local values = {}
    for k, v in pbody:gmatch("([%w_]+)%s*=%s*(%-?[%d%.]+)") do values[k] = v end
    local w = U.fromPawnValues(values)
    if not next(w) then return nil, "no stats this addon knows in that Pawn scale" end
    return { name = pname ~= "" and pname or "Pawn scale", w = w, pawn = true }
  end
  return nil, "that's not a weights string (EAH-UP:...) or a Pawn scale ( Pawn: v1: ... )"
end

-- Saves weights as a profile of the spec and picks it. The name is made unique ("Fury (2)").
function U.saveProfile(specKey, name, w)
  local all = U.profiles()
  local taken = {}
  for _, p in ipairs(all) do if p.spec == specKey then taken[p.name] = true end end
  name = tostring(name or "My weights"):gsub("[:|]", "")
  local base, n = name, 2
  while taken[name] do name = base .. " (" .. n .. ")"; n = n + 1 end
  local copy = {}
  for k, v in pairs(w) do if U.NAME[k] and tonumber(v) and v ~= 0 then copy[k] = tonumber(v) end end
  local p = { name = name, spec = specKey, w = copy }
  all[#all + 1] = p
  U.char().profile[specKey] = name
  U.changed()
  return p
end

function U.deleteProfile(specKey)
  local p = U.activeProfile(specKey)
  if not p then return false end
  local all = U.profiles()
  for i = #all, 1, -1 do if all[i] == p then table.remove(all, i) end end
  U.char().profile[specKey] = nil
  U.changed()
  return true, p.name
end

-- Previous or next of: built-in, then the spec's own profiles.
function U.stepProfile(specKey, dir)
  local list = U.profiles(specKey)
  local cur = U.char().profile[specKey]
  local idx = 0
  for i, p in ipairs(list) do if p.name == cur then idx = i end end
  idx = (idx + dir) % (#list + 1)
  U.char().profile[specKey] = idx > 0 and list[idx].name or nil
  U.changed()
  return idx > 0 and list[idx].name or "Built-in"
end

function U.setWeight(specKey, stat, v)
  local p = U.activeProfile(specKey)
  if not p then
    p = U.saveProfile(specKey, (U.spec(specKey) and U.spec(specKey).name or "My") .. " (mine)", (U.weights(specKey)))
  end
  v = tonumber(v)
  p.w[stat] = (v and v ~= 0) and v or nil
  U.changed()
  return p
end

---------------------------------------------------------------------------------------------------------------------
-- Item stats

local statCache, statCount = {}, 0   -- link or "id:suffix" -> stats; this session only

-- The link of an item version (the random suffix as its first bonus, the way the full scan reads it).
function U.linkOf(id, suffix)
  if suffix and suffix ~= 0 then return "item:" .. id .. "::::::::::::1:" .. suffix end
  return "item:" .. id
end

-- Stats of an item version or a link: { str = 5, dps = 12.3, ... }. nil while the game hasn't loaded the item. The
-- game's numbers first; English equip lines (Data.lua's effect lines, and the tooltip when asked) fill the rest.
function U.stats(link, id, opts)
  local hit = statCache[link]
  if hit then return hit end
  id = id or tonumber(tostring(link):match("item:(%d+)"))
  if not id then return nil end
  local getStats = (C_Item and C_Item.GetItemStats) or GetItemStats
  if C_Item and C_Item.IsItemDataCachedByID and not C_Item.IsItemDataCachedByID(id) then
    if C_Item.RequestLoadItemDataByID then pcall(C_Item.RequestLoadItemDataByID, id) end
    return nil
  end
  local full = tostring(link):find("|H", 1, true) and link or link
  local okS, t = false, nil
  if getStats then okS, t = pcall(getStats, full) end
  local st = {}
  if okS and type(t) == "table" then
    for mod, v in pairs(t) do
      local k = U.MODS[mod]
      v = ns.ok and ns.ok(v) or v
      if k and type(v) == "number" and v ~= 0 then
        if type(k) == "table" then
          for _, kk in ipairs(k) do st[kk] = math.max(st[kk] or 0, v) end
        else
          st[k] = (st[k] or 0) + v
        end
      end
    end
  end
  -- Data.lua's effect lines (the site's own, English)
  local e = ns.EFFECT and ns.EFFECT[id]
  local lines = ns.EFFECTLINES or {}
  if type(e) == "number" then U.parseLine(st, lines[e])
  elseif type(e) == "table" then for _, k in ipairs(e) do U.parseLine(st, lines[k]) end end
  if opts and opts.tooltip then st.tipRead = U.readTooltipLines(st, opts.tooltip) end
  statCount = statCount + 1
  if statCount > 8000 then statCache, statCount = {}, 0 end
  statCache[link] = st
  return st
end

-- Reads the tooltip's lines into st (for worn items: /eah up check). tipData is C_TooltipInfo's answer or a
-- function returning it. Returns true when a tooltip was read.
function U.readTooltipLines(st, tipData)
  local okT, d = pcall(function() return type(tipData) == "function" and tipData() or tipData end)
  if not okT or type(d) ~= "table" or type(d.lines) ~= "table" or #d.lines == 0 then return false end
  for _, l in ipairs(d.lines) do
    local txt = ns.ok and ns.ok(l.leftText) or l.leftText
    if type(txt) == "string" then U.parseLine(st, txt) end
  end
  return true
end

function U.forgetStats() statCache, statCount = {}, 0 end
function U.cacheSize() return statCount end

---------------------------------------------------------------------------------------------------------------------
-- Scores

local function procRate(e, role)
  -- hits per second we assume: melee about one a second (white and yellow), ranged one every two, spells and
  -- heals one cast every 2.5 seconds
  local t = e.t
  if t == "any" then t = (role == "caster" or role == "healer") and "spell" or role == "ranged" and "ranged" or "melee" end
  local hits = (t == "ranged" and 0.5) or ((t == "spell" or t == "heal") and 0.4) or 1
  local r
  if e.cd and e.cd > 0 then r = 1 / e.cd   -- a Use: effect, used on cooldown
  elseif e.ppm then r = e.ppm / 60 elseif e.ch then r = e.ch * hits else return 0 end
  if e.icd and e.icd > 0 then r = math.min(r, 1 / e.icd) end
  return r
end

-- The average worth of an item's procs and Use: effects (UpgradesData.lua, from wowsims): a stat buff counts as its
-- stats times its average uptime, damage as attack power (14 AP = 1 DPS) or spell damage (1 spell damage is about
-- 0.4 DPS), healing as healing, an extra attack as one main-hand swing. An estimate.
function U.procValue(id, w, role, wornMH)
  local list = data().procs and data().procs[id]
  if not list then return 0 end
  local v = 0
  for _, e in ipairs(list) do
    local uptime
    if e.k == "stat" then
      if e.cd and e.cd > 0 then
        uptime = math.min(1, (e.d or 0) / e.cd)
      else
        local r = procRate(e, role)
        uptime = r > 0 and (1 - math.exp(-(e.d or 0) * r)) or 0
      end
      for k, n in pairs(e.s or {}) do v = v + n * uptime * (w[k] or 0) end
    elseif e.k == "dmg" or e.k == "heal" then
      local dps = (e.avg or 0) * procRate(e, role)
      if e.k == "heal" then
        v = v + dps / 0.4 * (w.heal or 0)
      elseif (w.sp or 0) > (w.ap or 0) * 3 then
        v = v + dps / 0.4 * (w.sp or 0)
      else
        v = v + dps * 14 * math.max(w.ap or 0, w.rap or 0)
      end
    elseif e.k == "extra" then
      local swing = (wornMH or 30) * 2.6
      v = v + swing * (e.n or 1) * procRate(e, role) * 14 * (w.ap or 0)
    end
  end
  return v
end

-- An item version's score for the weights: every stat times its weight, weapon DPS as the slot's kind, plus procs
-- (setting on).
function U.score(st, w, group, id, role)
  if not st then return 0 end
  local s = 0
  for k, v in pairs(st) do
    if k == "dps" then
      s = s + v * (w[dpsKind(group)] or 0)
    elseif type(v) == "number" then
      s = s + v * (w[k] or 0)
    end
  end
  if id and U.get("procs") then s = s + U.procValue(id, w, role) end
  return s
end

---------------------------------------------------------------------------------------------------------------------
-- What is worn

-- worn[slot] = { link, id, key, equipLoc, stats } for the inventory slots we compare with.
function U.readWorn()
  local out = {}
  if U.testWorn then return U.testWorn end
  for _, slots in pairs(U.SLOTS) do
    for _, slot in ipairs(slots) do
      local okL, link = pcall(GetInventoryItemLink, "player", slot)
      link = okL and ns.ok and ns.ok(link) or (okL and link) or nil
      if type(link) == "string" then
        local id = tonumber(link:match("item:(%d+)"))
        local key = ns.variantOf and ns.variantOf(id, link) or (id .. ":0")
        local okI, _, _, _, equipLoc = pcall(C_Item.GetItemInfoInstant, id)
        out[slot] = { link = link, id = id, key = key, equipLoc = okI and equipLoc or nil, stats = U.stats(link, id) }
      end
    end
  end
  return out
end

local wornCache
function U.worn()
  if not wornCache then wornCache = U.readWorn() end
  return wornCache
end
function U.wornChanged() wornCache = nil; U.changed() end

-- An item's stats by weight key (its weapon DPS as the slot's kind), added into out times sign.
local function addStats(out, st, group, sign)
  for k, v in pairs(st or {}) do
    if type(v) == "number" then
      local key = k == "dps" and dpsKind(group) or k
      out[key] = (out[key] or 0) + v * sign
    end
  end
end

-- What a candidate of `group` is measured against, for the spec's weights: the worn score, the worn item, a word
-- for the special cases ("empty": fills an empty slot, "twohand": an off-hand while a two-hander is worn), and the
-- worn items it replaces { { item, group } }.
function U.against(group, equipLoc, w, role, worn)
  worn = worn or U.worn()
  local slots = U.SLOTS[group]
  if not slots then return nil end
  local function sc(slot, g)
    local it = worn[slot]
    if not it then return nil end
    return U.score(it.stats, w, g or group, it.id, role), it
  end
  if group == "finger" or group == "trinket" then
    local a, ia = sc(slots[1])
    local b, ib = sc(slots[2])
    if not ia or not ib then return 0, ia or ib, "empty", {} end
    if a <= b then return a, ia, nil, { { ia, group } } else return b, ib, nil, { { ib, group } } end
  end
  if group == "offhand" then
    local mh = worn[16]
    if mh and mh.equipLoc == "INVTYPE_2HWEAPON" then return nil, mh, "twohand", {} end
    local s, it = sc(17)
    if not it then return 0, nil, "empty", {} end
    return s, it, nil, { { it, group } }
  end
  if group == "mainhand" then
    local s, it = sc(16)
    if equipLoc == "INVTYPE_2HWEAPON" then
      -- a two-hander replaces both hands
      local o, oit = sc(17, "offhand")
      if not it and not oit then return 0, nil, "empty", {} end
      local parts = {}
      if it then parts[#parts + 1] = { it, "mainhand" } end
      if oit then parts[#parts + 1] = { oit, "offhand" } end
      return (s or 0) + (o or 0), it or oit, nil, parts
    end
    if not it then return 0, nil, "empty", {} end
    return s, it, nil, { { it, group } }
  end
  local s, it = sc(slots[1])
  if not it then return 0, nil, "empty", {} end
  return s, it, nil, { { it, group } }
end

-- The score of everything worn (the "% of your gear" an upgrade adds).
function U.wornTotal(w, role, worn)
  local total = 0
  for slot, it in pairs(worn or U.worn()) do
    if slot ~= 4 and slot ~= 19 then
      local g = U.GROUP_OF[it.equipLoc or ""]
      if g then total = total + U.score(it.stats, w, g == "mainhand" and slot == 17 and "offhand" or g, it.id, role) end
    end
  end
  return total
end

-- How a candidate compares, for one spec: { pct (the gain as a % of everything worn: "% of your gear", the one
-- measure every view shows; nil when nothing worn scores), slotPct (the gain over the worn item of that slot; nil for
-- an empty slot), delta (score points), score, vs (worn item), note ("empty" / "twohand"), ref (stat key), worth
-- (delta in that stat), err (the error margin of delta: twice its standard error from the weights' errors), same
-- (better, but within the margin: "about the same"), est (rests on estimated weights), why ({ {stat, amount} }: the
-- stat changes that matter most), mana (stats whose value depends on mana), threat (a tank's threat: the same
-- comparison with its threat weights; the verdict itself is survival) }. `with` = { w, meta } compares with other
-- weights (a tank's threat).
function U.compare(st, id, equipLoc, spec, worn, with)
  local group = U.GROUP_OF[equipLoc or ""]
  if not group then return nil end
  local w, _, _, _, meta = U.weights(spec)
  if with then w, meta = with.w, with.meta end
  local s = U.score(st, w, group, id, spec.role)
  local ws, vs, note, parts = U.against(group, equipLoc, w, spec.role, worn)
  local ref = U.refStat(w, spec.role)
  local r = { score = s, vs = vs, note = note, ref = ref, group = group }
  if note == "twohand" then return r end
  r.delta = s - (ws or 0)
  if note ~= "empty" and (ws or 0) > 0 then r.slotPct = r.delta / ws * 100 end
  r.parts = parts and #parts or 0
  r.worth = (w[ref] or 0) > 0 and r.delta / w[ref] or nil
  -- the stat differences, their error and the ones that matter
  local d = {}
  addStats(d, st, group, 1)
  for _, p in ipairs(parts or {}) do addStats(d, p[1].stats, p[2], -1) end
  local var, why, estPart, all = 0, {}, 0, 0
  for k, v in pairs(d) do
    local wk = w[k] or 0
    if v ~= 0 and wk ~= 0 then
      local e = U.weightErr(meta, k, wk) * v
      var = var + e * e
      all = all + math.abs(v * wk)
      if meta and (meta.src == "estimate" or (meta.est and meta.est[k])) then estPart = estPart + math.abs(v * wk) end
      why[#why + 1] = { k, v, v * wk }
    end
  end
  -- "estimate" when estimated weights carry a good part of the difference (a quarter or more)
  r.est = all > 0 and estPart >= 0.25 * all or nil
  table.sort(why, function(a, b) return math.abs(a[3]) > math.abs(b[3]) end)
  r.why = why
  r.err = 2 * math.sqrt(var)
  r.same = r.delta > 0 and r.delta <= r.err
  r.mana = meta and meta.mana
  local total = U.wornTotal(w, spec.role, worn)
  r.pct = total > 0 and r.delta / total * 100 or nil
  -- a tank: survival decides; threat is said beside it
  if not with and spec.role == "tank" and meta and meta.tps then
    r.threat = U.compare(st, id, equipLoc, spec, worn, { w = meta.tps, meta = { src = meta.src, se = meta.tpsSe } })
  end
  return r
end

-- A tank's threat beside its survival verdict: "threat +1.2% of your gear", "threat about the same", "less threat
-- (-0.8%)". nil when there are no threat weights.
function U.threatText(r)
  local t = r and r.threat
  if not t or not t.delta or t.note == "twohand" then return nil end
  if t.same or (t.delta <= 0 and t.delta >= -(t.err or 0)) then return "threat about the same" end
  if t.delta > 0 then return "threat " .. (t.pct and (U.pctText(t) .. " of your gear") or "higher") end
  return "less threat" .. (t.pct and (" (" .. ("%+.1f%%"):format(t.pct) .. ")") or "")
end

-- Whether a compare result counts as an upgrade with at least minPct (% of your gear).
function U.isUpgrade(r, minPct)
  if not r or r.note == "twohand" or not r.delta or r.delta <= 0 or r.same then return false end
  if not r.pct then return true end   -- nothing worn scores yet: any gain is one
  if r.note == "empty" then return r.pct >= (minPct or 0) end
  return r.pct >= (minPct or 0) and r.pct > 0.01
end

-- The checks before scoring: can the class use it, is it the armor type, is the level there. Returns ok, why
-- ("class", "armor", "level" with the level).
function U.usable(id, spec, info)
  local okI, _, _, _, equipLoc, _, classID, subID = pcall(C_Item.GetItemInfoInstant, id)
  if not okI or not equipLoc then return false, "unknown" end
  if not U.GROUP_OF[equipLoc] then return false, "notgear" end
  local class, level = U.class(), U.level()
  local can, why = U.canUse(class, classID, subID, equipLoc, 60)
  if not can then return false, "class" end
  if (equipLoc == "INVTYPE_WEAPONOFFHAND" or equipLoc == "INVTYPE_WEAPON") and false then return false end
  if equipLoc == "INVTYPE_WEAPONOFFHAND" and not U.canDualWield(class) then return false, "class" end
  if spec and not U.armorOK(class, math.max(level, 40 * ((info and info[4] or 0) >= 40 and 1 or 0)), spec.role, classID, subID, equipLoc, U.get("armor")) then
    return false, "armor"
  end
  local req = info and info[4] or 0
  if req > level then return false, "level", req end
  if why == "level40" and level < 40 then return false, "level", 40 end
  return true, nil, nil, equipLoc
end

-- The offhand-able groups of a one-hand weapon: the main hand, and the off hand when the class dual wields.
function U.groupsFor(equipLoc)
  local g = U.GROUP_OF[equipLoc or ""]
  if not g then return {} end
  if equipLoc == "INVTYPE_WEAPON" and U.canDualWield(U.class()) then return { "mainhand", "offhand" } end
  return { g }
end

---------------------------------------------------------------------------------------------------------------------
-- The upgrades in the last full scan

-- The newest full scan of the house: our own or the shared one, whichever is newer. Returns the scan and its source
-- ("own" or "shared"). A scan is this house's by its realm name, or by its realm ID (scans saved while the game
-- didn't say the realm's name: realm "" or "?", and the house key "?-Alliance").
function U.newestScan()
  local db = ns.db and ns.db()
  local hk = ns.houseOrFaction and ns.houseOrFaction()
  if not db or not hk then return nil end
  local realm, side = hk:match("^(.*)%-(%a+)$")
  if realm == "" or realm == "?" then realm = nil end
  local realmID
  if ns.realmInfo then
    local okR, _, id = pcall(ns.realmInfo)
    if okR and type(id) == "number" and id > 0 then realmID = id end
  end
  local mine
  for k = #(db.scans or {}), 1, -1 do
    local sc = db.scans[k]
    if sc.side == side and sc.rows and ((realm and sc.realm == realm) or (realmID and sc.realmID == realmID)) then
      mine = sc
      break
    end
  end
  local shared = ns.shared and ns.shared.scan(hk)
  if shared and (not mine or (shared.at or 0) > (mine.at or 0)) then return shared, "shared" end
  return mine, mine and "own" or nil
end

local job                 -- the read in progress: { scan, spec, rows, i, ... }
U.result = nil            -- the last result: { scan, source, at, spec, slots, gear, upgrades, pending }

local function inCombat() return InCombatLockdown and InCombatLockdown() end

local function filters()
  local max = U.get("max")
  return tonumber(max), tonumber(U.get("min")) or 0, U.get("rich") and true or false
end

-- How to order the options of a slot: rich mode = biggest upgrade; else most upgrade per gold (an empty slot by
-- its score). The max price is a ceiling either way.
function U.rank(a, b, rich)
  local function size(x) return x.cmp.pct or 1000 end
  if rich then
    local x, y = size(a), size(b)
    if x ~= y then return x > y end
    return (a.price or 0) < (b.price or 0)
  end
  local x, y = a.cmp.delta / math.max(a.price or 1, 1), b.cmp.delta / math.max(b.price or 1, 1)
  if x ~= y then return x > y end
  return size(a) > size(b)
end

-- One scan row, scored into out (per slot group).
local function consider(out, key, line, spec, worn, maxPrice, minPct)
  local id, suffix = key:match("^(%d+):(%-?%d+)$")
  id, suffix = tonumber(id), tonumber(suffix)
  if not id then return end
  local okI, _, _, _, equipLoc = pcall(C_Item.GetItemInfoInstant, id)
  if not okI or not U.GROUP_OF[equipLoc or ""] then return end
  out.gear = out.gear + 1
  local info = ns.itemInfo and ns.itemInfo(id)
  if not info then out.pending = out.pending + 1; return end
  local okU, why, needs = U.usable(id, spec, info)
  if not okU and why ~= "level" then return end
  local f = { strsplit(",", line) }
  local price = tonumber(f[1])
  if not price then return end   -- bids only
  local st = U.stats(U.linkOf(id, suffix), id)
  if not st then out.pending = out.pending + 1; return end
  for _, group in ipairs(U.groupsFor(equipLoc)) do
    local slot = out.slots[group]
    slot.usable = slot.usable + 1
    local loc = group == "offhand" and equipLoc == "INVTYPE_WEAPON" and "INVTYPE_WEAPONOFFHAND" or equipLoc
    local cmp = U.compare(st, id, loc, spec, worn)
    if cmp and cmp.note == "twohand" then
      slot.twohand = true
    elseif okU and (minPct or 0) > 0 and U.isUpgrade(cmp, 0) and not U.isUpgrade(cmp, minPct)
        and not (maxPrice and price > maxPrice) then
      slot.underMin = (slot.underMin or 0) + 1   -- an upgrade, but smaller than MIN % (the footer says so)
    elseif U.isUpgrade(cmp, minPct) then
      local name = (suffix ~= 0 and f[13] and f[13] ~= "") and f[13] or info[1]
      local entry = { key = key, id = id, suffix = suffix, name = name, quality = info[2], icon = info[8],
        price = price, qty = tonumber(f[4]), cmp = cmp, req = info[4] }
      if not okU then
        -- better, but above your level: noted as the next upgrade
        if not slot.nextLevel or needs < slot.nextLevel then slot.nextLevel = needs end
      elseif maxPrice and price > maxPrice then
        slot.overMax = (slot.overMax or 0) + 1
      else
        slot.better = slot.better + 1
        local list = slot.list
        list[#list + 1] = entry
      end
    end
  end
end

local function newResult(scan, source, spec)
  local r = { scan = scan, source = source, at = scan and scan.at, spec = spec, slots = {}, gear = 0, pending = 0, upgrades = 0 }
  for _, g in ipairs(U.ORDER) do r.slots[g] = { usable = 0, better = 0, list = {} } end
  return r
end

-- The best per slot, sorted, and the totals.
local function finish(r)
  local _, _, rich = filters()
  local total, n = 0, 0
  r.overMax, r.underMin = 0, 0
  for _, g in ipairs(U.ORDER) do
    local slot = r.slots[g]
    if slot.better == 0 then
      -- upgrades the filters hide in slots that show none (the footer names the filter to loosen)
      r.overMax = r.overMax + (slot.overMax or 0)
      r.underMin = r.underMin + (slot.underMin or 0)
    end
    table.sort(slot.list, function(a, b) return U.rank(a, b, rich) end)
    while #slot.list > 40 do table.remove(slot.list) end
    slot.best = slot.list[1]
    if slot.best then
      total, n = total + slot.best.price, n + 1
      r.upgrades = r.upgrades + slot.better
    end
  end
  r.total, r.count = total, n
  r.done = true
  return r
end

-- Scores every row of the newest scan for a spec in batches over frames (about 3 ms a frame), never in combat (it
-- waits for combat to end). onDone(result) when finished. A newer call replaces a running one.
function U.collect(spec, onDone, sync)
  if type(spec) == "string" then spec = U.spec(spec) end
  local scan, source = U.newestScan()
  local r = newResult(scan, source, spec)
  if not scan or not spec then
    r.done, r.none = true, not scan
    U.result = r
    if onDone then onDone(r) end
    return r
  end
  local keys = {}
  for key in pairs(scan.rows or {}) do keys[#keys + 1] = key end
  local mine = { keys = keys, i = 1, r = r }
  job = mine
  local worn = U.readWorn()
  wornCache = worn
  local maxPrice, minPct = filters()
  local clock = debugprofilestop or function() return 0 end
  local function step()
    if job ~= mine then return end
    if inCombat() and not sync then mine.waiting = true; return end   -- PLAYER_REGEN_ENABLED goes on
    mine.waiting = nil
    local start = clock()
    local n = 0
    while mine.i <= #keys do
      local key = keys[mine.i]
      mine.i = mine.i + 1
      pcall(consider, r, key, scan.rows[key], spec, worn, maxPrice, minPct)
      n = n + 1
      if not sync and (n >= 400 or (n % 25 == 0 and clock() - start > 3)) then break end
    end
    r.progress = (mine.i - 1) / math.max(1, #keys)
    if mine.i <= #keys then
      if U.onProgress then pcall(U.onProgress, r) end
      C_Timer.After(0, step)
      return
    end
    job = nil
    finish(r)
    U.result = r
    if onDone then onDone(r) end
  end
  mine.step = step
  step()
  return r
end

function U.busy() return job ~= nil end
function U.resume()
  if job and job.waiting and job.step then job.step() end
end

---------------------------------------------------------------------------------------------------------------------
-- Changes

U.listeners = {}
function U.changed()
  weightCache = {}
  for _, fn in ipairs(U.listeners) do pcall(fn) end
end
function U.onChange(fn) U.listeners[#U.listeners + 1] = fn end

-- A gain in % of your gear, short: "+6.5%", "+12%".
function U.shortPct(p)
  if not p then return "" end
  if math.abs(p) >= 9.95 then return ("%+.0f%%"):format(p) end
  return ("%+.1f%%"):format(p)
end

-- The gain as "% of your gear" ("+6.5%"); "fills an empty slot" when nothing worn scores to measure it against.
function U.pctText(r)
  if not r then return "" end
  if not r.pct then return r.note == "empty" and "fills an empty slot" or "" end
  return U.shortPct(r.pct)
end

-- What the worn item of a group is called in "(+136% over your worn helm)".
U.WORN_WORD = { head = "helm", neck = "necklace", shoulder = "shoulders", back = "cloak", chest = "chest",
  wrist = "bracers", hands = "gloves", waist = "belt", legs = "legs", feet = "boots", finger = "weaker ring",
  trinket = "weaker trinket", mainhand = "weapon", offhand = "off-hand", ranged = "ranged weapon" }

-- The slot-relative change in words: "+136% over your worn helm" (nil for an empty slot).
function U.slotText(r)
  if not r or not r.slotPct or not r.delta or r.delta <= 0 then return nil end
  local word = (r.group == "mainhand" and (r.parts or 0) > 1) and "weapons" or U.WORN_WORD[r.group] or "item"
  return ("%+.0f%% over your worn %s"):format(r.slotPct, word)
end

-- "worth about +12 Strength"
function U.worthText(r)
  if not r or not r.worth or not r.ref then return nil end
  local n = r.worth
  local fmt = math.abs(n) >= 10 and "%+.0f" or "%+.1f"
  return ("worth about %s %s"):format(fmt:format(n), U.NAME[r.ref] or r.ref)
end

-- Why: "+14 Strength, +10 Crit Rating, -5 Stamina (+136% over your worn helm)" (the biggest stat changes, by what
-- they're worth, and the slot-relative change in words), with "(estimate)" when estimated weights decide it.
function U.whyText(r, max)
  if not r or not r.why then return nil end
  local parts = {}
  for i = 1, math.min(max or 3, #r.why) do
    local k, v = r.why[i][1], r.why[i][2]
    local amount = (math.abs(v) >= 10 or v == math.floor(v)) and ("%+d"):format(math.floor(v + (v > 0 and 0.5 or -0.5))) or ("%+.1f"):format(v)
    parts[#parts + 1] = amount .. " " .. (U.NAME[k] or k) .. ((r.mana and r.mana[k]) and " (mana-dependent)" or "")
  end
  local text = table.concat(parts, ", ")
  local slot = U.slotText(r)
  if slot then text = text .. " (" .. slot .. ")" end
  if r.est then text = text .. " (estimate)" end
  return text
end

-- Money typed the player's way: "25g", "5s", "1g 50s", "2g50s", "7500" (copper). nil when it isn't money.
function U.parseMoney(text)
  text = tostring(text or ""):lower():gsub("%s+", "")
  if text == "" then return nil end
  if text:match("^%d+$") then return tonumber(text) end
  local total, any = 0, false
  for n, unit in text:gmatch("(%d+%.?%d*)([gsc])") do
    any = true
    total = total + tonumber(n) * (unit == "g" and 10000 or unit == "s" and 100 or 1)
  end
  local left = text:gsub("%d+%.?%d*[gsc]", "")
  if not any or left ~= "" then return nil end
  return math.floor(total + 0.5)
end

-- "1g 50s" for copper (as /eah up max takes it back).
function U.moneyShort(c)
  c = math.floor(tonumber(c) or 0)
  local g, si, co = math.floor(c / 10000), math.floor(c / 100) % 100, c % 100
  local out = {}
  if g > 0 then out[#out + 1] = g .. "g" end
  if si > 0 then out[#out + 1] = si .. "s" end
  if co > 0 or #out == 0 then out[#out + 1] = co .. "c" end
  return table.concat(out, " ")
end

-- Events: the worn gear, talents and combat
if CreateFrame then
  local ev = CreateFrame("Frame")
  for _, e in ipairs({ "PLAYER_EQUIPMENT_CHANGED", "CHARACTER_POINTS_CHANGED", "PLAYER_TALENT_UPDATE",
      "PLAYER_LEVEL_UP", "PLAYER_REGEN_ENABLED", "GET_ITEM_INFO_RECEIVED" }) do
    pcall(ev.RegisterEvent, ev, e)
  end
  local pendingInfo = false
  ev:SetScript("OnEvent", function(_, e)
    if e == "PLAYER_EQUIPMENT_CHANGED" or e == "PLAYER_LEVEL_UP" then
      U.wornChanged()
    elseif e == "CHARACTER_POINTS_CHANGED" or e == "PLAYER_TALENT_UPDATE" then
      U.changed()
    elseif e == "PLAYER_REGEN_ENABLED" then
      U.resume()
      if U.afterCombat then pcall(U.afterCombat) end
    elseif e == "GET_ITEM_INFO_RECEIVED" and not pendingInfo then
      -- a worn item that wasn't loaded yet: read again in a moment (one timer for a burst of them)
      pendingInfo = true
      C_Timer.After(1, function()
        pendingInfo = false
        if wornCache then
          for _, it in pairs(wornCache) do if not it.stats then wornCache = nil; U.changed(); break end end
        end
      end)
    end
  end)
end
